CHUNK = '      - infer task profiles,\n      - resolve path scopes,\n      - infer language from the task,\n      - semantically compare prose rules,\n      - decide PASS/FAIL/BLOCKED,\n      - compute per-run ruleset hashes.\n    """\n\n    def __init__(\n        self,\n        root: Path,\n        config: dict[str, Any],\n        shared_rules: dict[str, Rule],\n        local_rules: dict[str, Rule],\n        profiles: dict[str, Profile],\n    ):\n        self.root = root\n        self.config = config\n        self.shared_rules = shared_rules\n        self.local_rules = local_rules\n        self.profiles = profiles\n        self.rules = {**shared_rules, **local_rules}\n        self.specializations: dict[str, Rule] = {}\n        self._validate_and_index()\n\n    @classmethod\n    def load(cls, root: str | Path) -> AgentEngineeringStandard:\n        root = Path(root)\n        config = _read_json(root / "config.json")\n        if not isinstance(config, dict):\n            raise StandardConfigurationError("config.json must be a JSON object")\n\n        shared_rules: dict[str, Rule] = {}\n        for obj, origin in _iter_rule_objects(root / "rules"):\n            rule = _parse_rule(obj, origin)\n            if rule.id in shared_rules:\n                raise StandardConfigurationError(f"Duplicate shared rule id: {rule.id}")\n            if rule.specializes is not None:\n                raise StandardConfigurationError(\n                    f"{rule.id}: shared rules must not declare specializes"\n                )\n            shared_rules[rule.id] = rule\n\n        local_rules: dict[str, Rule] = {}\n        for obj, origin in _iter_rule_objects(root / "local-rules"):\n            rule = _parse_rule(obj, origin)\n            if rule.id in shared_rules or rule.id in local_rules:\n                raise StandardConfigurationError(\n                    f"Local rule id collides with an existing rule: {rule.id}"\n                )\n            local_rules[rule.id] = rule\n\n        profiles: dict[str, Profile] = {}\n        profiles_path = root / "profiles"\n        for file in sorted(profiles_path.glob("*.json")):\n            profile = _parse_profile(_read_json(file), file)\n            if profile.id in profiles:\n                raise StandardConfigurationError(f"Duplicate profile id: {profile.id}")\n            profiles[profile.id] = profile\n\n        return cls(\n            root=root,\n            config=config,\n            shared_rules=shared_rules,\n            local_rules=local_rules,\n            profiles=profiles,\n        )\n\n    @property\n    def governing_context_id(self) -> str:\n        value = self.config.get("governing_context_id")\n        if not isinstance(value, str) or not value:\n            raise StandardConfigurationError(\n                "config.json must supply a non-empty governing_context_id"\n            )\n'
